function validateConfig(config) {
  const c = { ...config };
  if (!/^\d{5}$/.test(String(c.zipcode))) throw new Error('Set zipcode to five digits.');
  if (![5, 10, 25, 50, 100].includes(Number(c.radius))) throw new Error('Choose radius 5, 10, 25, 50 or 100.');
  for (const field of ['minPrice', 'maxPrice', 'minBeds']) {
    if (!Number.isFinite(Number(c[field])) || Number(c[field]) < 0) throw new Error(`Set a nonnegative ${field}.`);
  }
  if (Number(c.minPrice) > Number(c.maxPrice)) throw new Error('minPrice must not exceed maxPrice.');
  if (!/^[A-Za-z0-9_-]{20,}$/.test(String(c.spreadsheetId)) || String(c.spreadsheetId).startsWith('REPLACE')) {
    throw new Error('Set spreadsheetId to your Google Sheets document ID.');
  }
  if (!String(c.sheetName || '').trim()) throw new Error('Set sheetName to your watchlist tab name.');
  if (typeof c.sendEmail !== 'boolean') throw new Error('sendEmail must be a boolean.');
  if (c.sendEmail && !/^[^\s@,;<>]+@[^\s@,;<>]+\.[^\s@,;<>]+$/.test(String(c.recipient))) {
    throw new Error('Set recipient to one email address you control before enabling email.');
  }
  return c;
}

return [{ json: validateConfig($input.first().json) }];

function normalizeResponse(body, now) {
  const sources = ['auction', 'hud', 'fanniemae', 'freddiemac', 'redfin'];
  if (!body || !body.meta || !Array.isArray(body.listings) || body.error) throw new Error('Unexpected API response; no rows or email written.');
  const m = body.meta;
  if (m.failedSources !== undefined && !Array.isArray(m.failedSources)) throw new Error('Invalid failedSources metadata.');
  if (m.failedSources?.length) throw new Error(`Incomplete scan: ${m.failedSources.join(', ')} failed. Retry later; no rows or email written.`);
  if (!Array.isArray(m.sources) || sources.some(s => !m.sources.includes(s))) throw new Error('The response must cover all five configured sources.');
  if (!Number.isInteger(m.totalCount) || m.totalCount < 0) throw new Error('Invalid totalCount metadata.');
  if (m.totalCount > 500 || m.totalCount !== body.listings.length || (m.offset || 0) !== 0) {
    throw new Error(`Incomplete page (${body.listings.length}/${m.totalCount}). This template caps a watchlist at 500 matches; narrow the ZIP/radius/price filters. No rows or email written.`);
  }
  const clean = v => v === null || v === undefined ? '' : String(v).replace(/[\r\n\t]+/g, ' ').trim();
  const number = v => v === null || v === undefined || v === '' ? '' : (Number.isFinite(Number(v)) ? Number(v) : '');
  const byKey = new Map();
  for (const l of body.listings) {
    if (!l || !sources.includes(l.source) || !['string', 'number'].includes(typeof l.listingId) || !clean(l.listingId)) {
      throw new Error('A listing is missing a supported source or listingId; no rows written.');
    }
    const id = clean(l.listingId);
    const link = clean(l.propertyLink);
    if (link && !/^https?:\/\/[^\s]+$/i.test(link)) throw new Error('A listing has an invalid property link; no rows written.');
    const key = `${l.source}:${encodeURIComponent(id)}`;
    if (byKey.has(key)) continue;
    byKey.set(key, {
      listing_key: key, source: l.source, listing_id: id, address: clean(l.address),
      price: number(l.openingBid), bedrooms: number(l.bedrooms), bathrooms: number(l.bathrooms),
      property_type: clean(l.propertyType), asset_type: clean(l.assetType), status: clean(l.status),
      property_link: link, first_seen: now, last_seen: now, notified_at: '', gmail_message_id: '',
    });
  }
  return { rows: [...byKey.values()], checked_at: now, total_matches: m.totalCount };
}

return [{ json: normalizeResponse($input.first().json, new Date().toISOString()) }];

function prepareNewRows(scan, existing) {
  const history = new Map();
  for (const row of existing) {
    if (!row || !row.listing_key) {
      if (row && Object.values(row).some(v => v !== '' && v !== null && v !== undefined)) throw new Error('A populated history row is missing listing_key. Repair the sheet before running.');
      continue; // n8n Always Output Data emits an empty object for a header-only sheet.
    }
    const key = String(row.listing_key);
    if (history.has(key)) throw new Error(`Duplicate history key ${key}. Keep one row per listing_key before running.`);
    history.set(key, row);
  }
  const pending = [];
  for (const row of scan.rows) {
    const old = history.get(row.listing_key);
    if (old && String(old.notified_at || '').trim()) continue;
    pending.push({ ...row, first_seen: old?.first_seen || row.first_seen });
  }
  return pending;
}

return prepareNewRows($('Validate complete scan').first().json, $input.all().map(i => i.json)).map(json => ({ json }));

function buildDigest(rows, expected, config) {
  // Only mail the batch after every pending row was accepted by the Sheets node.
  const keys = new Set(rows.map(r => r.listing_key));
  if (rows.length !== expected.length || keys.size !== expected.length || expected.some(r => !keys.has(r.listing_key))) {
    throw new Error('Sheets did not return the complete pending batch; email stopped.');
  }
  if (!rows.length) return null;
  const lines = [
    `${rows.length} unnotified match${rows.length === 1 ? '' : 'es'} for ZIP ${config.zipcode} (radius setting: ${config.radius} miles).`,
    'These are first-observed matches for this watchlist, including any pending delivery from a previous run.',
    'Source coverage and search areas vary. Listings are cached for up to about one hour.',
    '',
  ];
  for (const row of rows) {
    const price = row.price === '' ? 'Price unavailable' : `$${Number(row.price).toLocaleString('en-US')}`;
    lines.push(`${row.address || '(address unavailable)'} | ${price} | ${row.bedrooms === '' ? '?' : row.bedrooms} beds`,
      `Source: ${row.source}; type: ${row.asset_type || row.property_type || 'unspecified'}; status: ${row.status || 'unspecified'}`,
      `First observed: ${row.first_seen}`, row.property_link || 'Source link unavailable', '');
  }
  lines.push(`Watchlist history: https://docs.google.com/spreadsheets/d/${config.spreadsheetId}/edit`, '',
    'An opening bid or asking price is not a final purchase price. Source inventory can include privately owned auctions and other listings. Verify foreclosure/REO status, availability, terms and property details at the source.');
  return { recipient: config.recipient, subject: `ZIP ${config.zipcode}: ${rows.length} watchlist match${rows.length === 1 ? '' : 'es'}`, message: lines.join('\n'), rows };
}

const digest = buildDigest($input.all().map(i => i.json), $('Find unnotified matches').all().map(i => i.json), $('Validate settings').first().json);
return digest ? [{ json: digest }] : [];

function acknowledgeDelivery(result, digest, now) {
  if (!result || typeof result.id !== 'string' || !result.id) throw new Error('Gmail did not confirm a message ID. Rows remain pending; inspect Sent before retrying.');
  return digest.rows.map(row => ({ ...row, notified_at: now, gmail_message_id: result.id }));
}

return acknowledgeDelivery($input.first().json, $('Build email preview').first().json, new Date().toISOString()).map(json => ({ json }));
